"""`.eyewhite sticker`: generated by export_nodes.py from face_cards.blend; kept by hand from then on."""

NAME = '.eyewhite sticker'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Shader', 'NodeSocketShader')
    t.socket('INPUT', 'Color', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Color', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))

    t.node('ShaderNodeEmission', 'Emission', props={
        'location': (-40.0, -100.0),
    })
    t.node('ShaderNodeBsdfTransparent', 'Transparent BSDF', props={
        'location': (-40.0, 100.0),
    })
    t.node('ShaderNodeMixShader', 'Mix Shader', props={
        'location': (210.0, 20.0),
    })
    t.node('ShaderNodeMath', 'Math', props={
        'location': (-228.3363, -4.985962),
        'label': 'Alpha = white alpha x mask',
        'operation': 'MULTIPLY',
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (410.0, 0.0),
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-428.3363, 0.0),
    })

    t.link('Transparent BSDF', 'BSDF', 'Mix Shader', 'Shader')
    t.link('Emission', 'Emission', 'Mix Shader', 'Shader_001')
    t.link('Math', 'Value', 'Mix Shader', 'Fac')
    t.link('Group Input', 0, 'Emission', 'Color')
    t.link('Group Input', 'Alpha', 'Math', 'Value')
    t.link('Mix Shader', 'Shader', 'Group Output', 'Shader')
    t.link('Group Input', 2, 'Math', 'Value_001')
    return t
